head.script:
scwin.fireDbClick = function(node) {
    if (document.createEventObject) {
        node.fireEvent('ondblclick');
    } else if (document.createEvent) {
        var evt = document.createEvent('MouseEvents');
        evt.initEvent('dblclick', true, false);
        node.dispatchEvent(evt);
    } else if (typeof node.ondblclick == 'function') {
        node.ondblclick();
    }
}
scwin.Dbclick = function(id) {
    var el = WebSquare.wUnit.getDomById($p.id + id);
    scwin.fireDbClick(el);
}
scwin.checkVal = function() {
    return WebSquare.wUnit.getJq('#G_gridView1___selectbox_col1_itemTable_0').width() > WebSquare.wUnit.getJq('#gridView1').width() && WebSquare.wUnit.getJq('#G_gridView1___selectbox_col1_itemTable_0').width() < WebSquare.wUnit.getJq('#G_gridView1___selectbox_col1_itemTable').width();
}
scwin.checkVal1 = function() {
    return WebSquare.wUnit.getJq('#G_gridView1___selectbox_col1_itemTable_1').width() > WebSquare.wUnit.getJq('#gridView1').width() && WebSquare.wUnit.getJq('#G_gridView1___selectbox_col1_itemTable_1').width() < WebSquare.wUnit.getJq('#G_gridView1___selectbox_col1_itemTable').width();
}
scwin.unitTest = function() {
    //init
    // WebSquare.wUnit.start();
    //Test step 1. 샘플파일을 실행 후 항목값에 마우스를 더블클릭한다.
    //1. Run the sample file and double-click on the item value.
    //Verify step 1. The value is displayed in the combo box and all the long strings are displayed.
    WebSquare.wUnit.addCommand("set", "scwin.Dbclick($p.id+'gridView1_cell_0_0')");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#G_gridView1___selectbox_col1_itemTable').css('display') == 'block'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('G_gridView1___selectbox_col1_itemTable_0').innerText == '12345613213232323232'", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('G_gridView1___selectbox_col1_itemTable_1').innerText == '3erewawerewre'", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function 
    //Created by: Thuyet.Pham
    //Created date: 27-Feb-2018
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
